import { useState } from 'react';

export default function App() {
  const [count, setCount] = useState(0);
  // Three async ticks: updater form survives stale snapshots.
  function bumpLater() {
    for (let i = 0; i < 3; i++) {
      setTimeout(() => setCount(c => c + 1), 100 * i);
    }
  }
  return (
    <div>
      <p>count = {count}</p>
      <button onClick={bumpLater}>+3 (staggered)</button>
    </div>
  );
}
